package com.guocheng.mediapocket;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;import java.util.*;import java.lang.reflect.*;
public final class SourceSubtitleLoader {
 static void set(Object target,String name,Object value)throws Exception{for(Class<?> c=target.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);f.set(target,value);return;}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(name);}
 static JSONArray list(Activity a){Object stream=OnlineSubtitleSearch.field(a,"stream");return stream instanceof JSONObject?((JSONObject)stream).optJSONArray("subtitles"):null;}
 public static void start(Object session){Object owner=OnlineSubtitleSearch.field(session,"a");if(!(owner instanceof Activity))return;Activity a=(Activity)owner;SharedPreferences p=a.getSharedPreferences("data",0);String id=String.valueOf(OnlineSubtitleSearch.field(a,"id"));if(p.getBoolean("subtitleDisabled:"+id,false))return;String saved=p.getString("subtitleUrl:"+id,"");if(!saved.isEmpty()){try{OnlineSubtitleSearch.call(a,"loadSub",new Class<?>[]{String.class},saved);}catch(Exception ignored){}return;}JSONArray subs=list(a);if(subs!=null&&subs.length()>0)load(a,subs,true);}
 static void choose(Activity a){JSONArray subs=list(a);if(subs==null||subs.length()==0){OnlineSubtitleSearch.message(a,"当前线路没有返回外挂字幕，可尝试内嵌字幕或在线搜索。");return;}String[] labels=new String[subs.length()];for(int i=0;i<labels.length;i++){JSONObject s=subs.optJSONObject(i);labels[i]=s==null?"字幕":s.optString("name",s.optString("lang","字幕 "+(i+1)));}new AlertDialog.Builder(a).setTitle("线路字幕 · "+labels.length+" 条").setItems(labels,(d,n)->load(a,new JSONArray().put(subs.optJSONObject(n)),false)).setNegativeButton("取消",null).show();}
 static void load(Activity a,JSONArray subs,boolean automatic){final int token;try{Object g=OnlineSubtitleSearch.field(a,"generation");token=(g instanceof Integer?(Integer)g:0)+1;set(a,"generation",token);}catch(Exception e){return;}String lang=a.getSharedPreferences("data",0).getString("subtitleLanguage","zho");ArrayList<JSONObject> items=new ArrayList<>();for(int i=0;i<Math.min(100,subs.length());i++){JSONObject s=subs.optJSONObject(i);if(s!=null)items.add(s);}if(automatic)items.sort((x,y)->Integer.compare(OnlineSubtitleSearch.rank(x.optString("lang",x.optString("name")),lang),OnlineSubtitleSearch.rank(y.optString("lang",y.optString("name")),lang)));while(items.size()>8)items.remove(items.size()-1);OnlineSubtitleSearch.IO.execute(()->{String failure="未识别到可用字幕";long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(30);for(JSONObject item:items){if(System.nanoTime()>deadline)break;if(a.isFinishing()||!Integer.valueOf(token).equals(OnlineSubtitleSearch.field(a,"generation")))return;try{Map<String,String> headers=new LinkedHashMap<>();JSONObject declared=item.optJSONObject("header");if(declared!=null){Iterator<String> keys=declared.keys();while(keys.hasNext()){String key=keys.next();headers.put(key,declared.optString(key));}}byte[] bytes=SubtitleHttp.download(item.optString("url"),headers);if(bytes.length>2*1024*1024)throw new Exception("字幕文件过大");String text=SubtitleTextRules.timeline(SubtitleTextRules.decode(bytes));Method parse=Class.forName("com.guocheng.mediapocket.SubtitleParser").getDeclaredMethod("parse",String.class);parse.setAccessible(true);Object cues=parse.invoke(null,text);if(!(cues instanceof ArrayList)||((ArrayList)cues).isEmpty())throw new Exception("此文件不是可加载的 SRT / VTT / ASS 字幕");a.runOnUiThread(()->{if(a.isFinishing()||!Boolean.TRUE.equals(OnlineSubtitleSearch.field(a,"alive"))||!Integer.valueOf(token).equals(OnlineSubtitleSearch.field(a,"generation")))return;try{set(a,"cues",cues);OnlineSubtitleSearch.subtitleEvent(a,"字幕交付播放器："+((ArrayList)cues).size()+" 条时间轴 · "+item.optString("provider",item.optString("name","线路字幕")));a.getSharedPreferences("data",0).edit().putBoolean("subtitleDisabled:"+String.valueOf(OnlineSubtitleSearch.field(a,"id")),false).apply();Toast.makeText(a,"已载入线路字幕 · "+item.optString("name",item.optString("lang","字幕")),Toast.LENGTH_SHORT).show();}catch(Exception ignored){}});return;}catch(Exception e){failure=SourceSearchClient.reason(e);OnlineSubtitleSearch.subtitleEvent(a,"字幕下载或解析失败："+item.optString("provider",item.optString("name","线路字幕"))+" · "+failure);}}final String error=failure;a.runOnUiThread(()->{if(a.isFinishing()||!Integer.valueOf(token).equals(OnlineSubtitleSearch.field(a,"generation")))return;if(automatic)Toast.makeText(a,"线路字幕未加载，可在字幕菜单搜索或选择内嵌字幕",Toast.LENGTH_LONG).show();else OnlineSubtitleSearch.message(a,"线路字幕加载失败："+error);});});}
}
